// Manual lane: normalize the fetched proof issue into the shared shape.
// Manual proof runs are keyed on issue identity + updated_at: re-running
// against an unchanged issue is a duplicate (suppressed); a fresh proof
// (issue edited) yields a new key. The 'manual:' prefix keeps these keys
// disjoint from webhook delivery keys.
const issue = $input.first().json;
const repoFullName = 'ebyron357/LifeOS-Enterprise';
return [{
  json: {
    source: 'manual',
    idempotencyKey: 'manual:' + repoFullName + ':' + issue.number + ':' + (issue.updated_at || 'na'),
    quarantineReason: null,
    deliveryId: null,
    ghEvent: 'manual-proof',
    action: 'manual',
    number: issue.number,
    title: issue.title || '',
    body: issue.body || '',
    html_url: issue.html_url || '',
    repository_full_name: repoFullName,
    repository_url: issue.repository_url || '',
    issue_updated_at: issue.updated_at || '',
    sender: (issue.user && issue.user.login) || '',
  },
}];

// Proof-token validation. The stale hardcoded token
// (LIFEOS-AUTO-PROOF-20260811-A) is removed as the verification
// mechanism. Controlled proof tokens follow the dated family below; the
// exact token found is extracted and carried into all downstream
// evidence (claim rows, ClickUp comment, suppression logs).
const item = $input.first().json;
const expectedRepo = 'ebyron357/LifeOS-Enterprise';
const TOKEN_PATTERN = /LIFEOS-IDEMPOTENCY-FINAL-\d{8}-[A-Z0-9]+/;
const text = (item.title || '') + '\n' + (item.body || '');
const match = text.match(TOKEN_PATTERN);
const repoMatch =
  item.repository_full_name === expectedRepo ||
  (item.html_url || '').includes(expectedRepo) ||
  (item.repository_url || '').includes(expectedRepo);
const tokenMatch = !!match;
return [{
  json: Object.assign({}, item, {
    valid: repoMatch && tokenMatch,
    repoMatch,
    tokenMatch,
    token: match ? match[0] : null,
    runTimestamp: new Date().toISOString(),
  }),
}];

// Deterministic winner election over the durable Data Table claims.
// Every delivery inserts its own claim row (monotonic auto-increment id)
// BEFORE any ClickUp mutation. After a 2s visibility-settlement window
// all claim rows for the key are fetched: the execution owning the
// LOWEST row id is the single winner (FIRST); every other execution is a
// DUPLICATE and is suppressed. Anomalies (no rows, own claim invisible)
// fail closed: no ClickUp mutation.
const norm = $('Validate Proof').first().json;
const myExecId = String($execution.id);
const rows = $input.all().map(function (i) { return i.json; }).filter(function (r) { return r && r.id !== undefined && r.key; });
if (rows.length === 0) {
  return [{ json: Object.assign({}, norm, {
    idempotencyDecision: 'datastore_failure',
    idempotencyDetail: 'Claim fetch returned no rows after a successful insert; store unreadable or inconsistent. Failing closed: no ClickUp mutation.',
    myExecutionId: myExecId,
  }) }];
}
const sorted = rows.slice().sort(function (a, b) { return Number(a.id) - Number(b.id); });
const winner = sorted[0];
const mine = sorted.find(function (r) { return String(r.executionId) === myExecId; });
if (!mine) {
  return [{ json: Object.assign({}, norm, {
    idempotencyDecision: 'datastore_failure',
    idempotencyDetail: 'Own claim row not visible after insert; store inconsistent. Failing closed: no ClickUp mutation.',
    myExecutionId: myExecId,
    claimCount: sorted.length,
  }) }];
}
const isFirst = String(winner.executionId) === myExecId;
return [{ json: Object.assign({}, norm, {
  idempotencyDecision: isFirst ? 'first' : 'duplicate',
  myExecutionId: myExecId,
  myClaimRowId: mine.id,
  winnerExecutionId: String(winner.executionId),
  winnerClaimRowId: winner.id,
  winnerClaimedAt: winner.claimedAt,
  claimCount: sorted.length,
  allClaimExecutionIds: sorted.map(function (r) { return String(r.executionId); }),
}) }];

