// Terminal suppression sink — NO ClickUp mutation on this path.
// decision: 'duplicate' | 'quarantine' | 'datastore_failure'.
const item = $input.first().json;
const decision = item.idempotencyDecision || (item.quarantineReason ? 'quarantine' : 'unknown');
const record = {
  suppressed: true,
  decision: decision,
  idempotencyKey: item.idempotencyKey || null,
  reason: item.quarantineReason || item.idempotencyDetail || (decision === 'duplicate'
    ? 'Duplicate delivery: key already claimed by execution ' + item.winnerExecutionId + ' (claim row ' + item.winnerClaimRowId + ', claimed at ' + item.winnerClaimedAt + ').'
    : null),
  deliveryId: item.deliveryId || null,
  source: item.source,
  issueNumber: item.number,
  token: item.token || null,
  myExecutionId: item.myExecutionId || String($execution.id),
  winnerExecutionId: item.winnerExecutionId || null,
  claimCount: item.claimCount || null,
  clickUpMutations: 0,
  timestamp: new Date().toISOString(),
};
console.log('[idempotency] SUPPRESSED ' + JSON.stringify(record));
return [{ json: record }];

// Datastore hard-failure sink (claim insert or claim fetch errored).
// Fail closed per the closeout contract: when the idempotency store
// cannot be read, written, or validated, NO ClickUp mutation occurs.
const item = $input.first().json;
const record = {
  suppressed: true,
  decision: 'datastore_failure',
  errorMessage: (item && item.error && (item.error.message || item.error.description)) || JSON.stringify(item),
  executionId: String($execution.id),
  clickUpMutations: 0,
  timestamp: new Date().toISOString(),
};
console.log('[idempotency] DATASTORE_FAILURE fail-closed ' + JSON.stringify(record));
return [{ json: record }];

// Webhook lane: normalize GitHub issues event + derive idempotency key.
// Primary key source: X-GitHub-Delivery header (PR #53 contract). GitHub
// reuses the same delivery GUID when a delivery is redelivered, so it is
// the canonical retry/redelivery identity. Event identity (repo, event,
// action, issue number) is appended to harden against key collisions.
// Fail-closed: absent header => no key => quarantined downstream, no
// ClickUp mutation.
const raw = $input.first().json;
const headers = raw.headers || {};
const payload = raw.body || raw;
const issue = payload.issue || {};
const repo = payload.repository || {};
const deliveryId = headers['x-github-delivery'] || headers['X-GitHub-Delivery'] || null;
const ghEvent = headers['x-github-event'] || 'unknown';
const action = payload.action || 'unknown';
const repoFullName = repo.full_name || '';
const idempotencyKey = deliveryId
  ? 'gh:' + deliveryId + ':' + repoFullName + ':' + ghEvent + ':' + action + ':' + (issue.number != null ? issue.number : 'na')
  : null;
return [{
  json: {
    source: 'webhook',
    idempotencyKey,
    quarantineReason: deliveryId ? null : 'X-GitHub-Delivery header absent; event quarantined for manual review (fail-closed)',
    deliveryId,
    ghEvent,
    action,
    number: issue.number,
    title: issue.title || '',
    body: issue.body || '',
    html_url: issue.html_url || '',
    repository_full_name: repoFullName,
    repository_url: repo.html_url || ('https://github.com/' + repoFullName),
    issue_updated_at: issue.updated_at || '',
    sender: (payload.sender && payload.sender.login) || '',
  },
}];
